input.sparql:
SELECT ?s ?point ?ts WHERE {
  ?s a brick:Basement .
  ?s brick:hasPoint ?p .
  ?p a brick:ZoneTemperatureSensor ; rdfs:label ?point .
  ?p ref:hasTimeseriesId ?ts .
}

SELECT ?s ?cls ?label WHERE {
  ?s rdfs:label ?label .
  ?s a ?cls .
  FILTER(lcase(str(?label)) LIKE "%basement%")
}

SELECT ?p ?cls ?label WHERE {
  ?p a ?cls ; rdfs:label ?label .
  FILTER(lcase(str(?label)) LIKE "%temp%")
} LIMIT 50

SELECT ?s ?cls ?label WHERE {
  ?s a ?cls .
  FILTER(lcase(str(?label)) LIKE "%basement%")
  ?s rdfs:label ?label .
}

SELECT DISTINCT ?pred WHERE {
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label "Basement" .
  ?zone ?pred ?o .
}

SELECT ?p ?cls ?label WHERE {
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label "Basement" .
  ?zone brick:hasPoint ?p .
  ?p a ?cls .
  OPTIONAL { ?p rdfs:label ?label }
}

SELECT ?ts WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor .
  ?p ref:hasTimeseriesId ?ts .
  FILTER(str(?p) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F1_Z01.Zone_Air_Temperature_Sensor")
}

SELECT ?o WHERE {
  ?p ref:hasTimeseriesId ?ts .
  FILTER(CONTAINS(str(?ts), "1") || true)
} LIMIT 5
